                <DialogTitle>Custom date range</DialogTitle>
                <DialogDescription>
                  Choose the dates to include in your charts.
                </DialogDescription>
              </DialogHeader>
              <FieldGroup>
                <Field>
                  <FieldLabel htmlFor="dashboard-from">Start date</FieldLabel>
                  <Input
                    id="dashboard-from"
                    max={customRange.to}
                    name="from"
                    onChange={(event) =>
                      setCustomRange({
                        ...customRange,
                        from: event.target.value,
                      })
                    }
                    required
                    type="date"
                    value={customRange.from}
                  />
                </Field>
                <Field>
                  <FieldLabel htmlFor="dashboard-to">End date</FieldLabel>
                  <Input
                    id="dashboard-to"
                    min={customRange.from}
                    name="to"
                    onChange={(event) =>
                      setCustomRange({ ...customRange, to: event.target.value })
                    }
                    required
                    type="date"
                    value={customRange.to}
                  />
                </Field>
              </FieldGroup>
              <DialogFooter>
                <Button
                  onClick={() => setCustomRange(null)}
                  type="button"
                  variant="outline"
                >
                  Cancel
                </Button>
                <Button className={press} type="submit">
                  Apply range
                </Button>
              </DialogFooter>
            </form>
          )}
        </DialogContent>
      </Dialog>
    </>
  );
}

